const e={meta:{propertyTypes:{Hus:"House",Ejerlejlighed:"Owner-occupied flat",Andel:"Co-op flat (andel)",Leje:"Rental"},trackLabels:{buy:"My purchase",sell:"My sale",rentIn:"Renting · moving in",rentOut:"Renting · moving out"},stages:["Preparation","Agreement & approval","Ready for handover","Completion"],contextLabels:{buy:"My purchase",sell:"My sale",rentIn:"Renting in",rentOut:"Renting out",common:"The move itself",incoming:"New home",outgoing:"Previous home"},transport:{Selv:"Myself",Flyttefirma:"Moving company"},titleVariants:{"lease-heat":{outgoing:"Arrange transfer or termination of the heat-pump lease",incoming:"Clarify takeover and start date of the heat-pump lease"},solar:{incoming:"Clarify takeover of solar-panel and metering agreements"}}},categories:{Adresse:"Address",Sundhed:"Health",Økonomi:"Finances",Forsikring:"Insurance","El & varme":"Electricity & heating",Ladning:"EV charging",Varmeleasing:"Heat-pump lease",Abonnementer:"Subscriptions",Boligaftaler:"Housing agreements",Familie:"Family",Transport:"Transport",Pakning:"Packing",Overtagelse:"Handover",Praktisk:"Practical",Flyttedag:"Moving day",Klargøring:"Preparation",Udpakning:"Unpacking"},profile:{charging:"EV charger or charging subscription",leasedHeat:"Leased heat pump or other leased heat source",gas:"Gas contract",children:"Children, school or daycare",pets:"Pets",car:"Car or parking permit",alarm:"Alarm or monitoring subscription",services:"Service agreements, e.g. window cleaning or gardening help",benefits:"Housing benefit, SU (student grant) or other public benefits",business:"Business registered at the home address",care:"Home care, assistive equipment or ongoing treatment",association:"Owners', co-op or homeowners' association",privacy:"Name and address protection",proxy:"I am helping someone else with their move",solar:"Solar panels or other energy production",student:"Studies, SU or Ungdomskort (youth travel pass)",pension:"Pension",firstHome:"First home or changed household",special:"Special registrations or permits"},checklist:{address:{title:"Report your change of address to the National Register (folkeregistret)",guide:"Use the day you actually move in and live at the address. Report no later than five days after. Check your municipality's self-service for when you can report. Keep the receipt."},"address-confirm":{title:"Check the confirmation of your change of address",guide:"Check the address, the date and the people covered by the report. Follow up on any messages in Digital Post."},doctor:{title:"Decide on your GP and change doctor if needed",guide:"You can keep your GP or look for a new one with open lists. A free change of doctor must be made together with the change-of-address report; check that you receive a confirmation."},healthcard:{title:"Check your health card and GP details",guide:"Check that your registered details are correct, and follow messages from the municipality or region."},dentist:{title:"Give your dentist and other practitioners your new address",guide:"Go through dentist, physiotherapist, specialist, pharmacy deliveries and other relevant contacts."},medicine:{title:"Arrange medicine and essential equipment for the moving days",guide:"Pack medicine, prescriptions, glasses and important equipment so they are accessible during the move."},mailbox:{title:"Put your name on the letterbox, door and any entry phone",guide:"Put the household's names on the new address and arrange removal at the old one."},senders:{title:"Update your address with senders and in delivery profiles",guide:"Go through online shops, parcel lockers, meal kits, newspapers and regular deliveries. Check open orders to the old address."},employer:{title:"Notify your employer and any relevant educational institutions",guide:"Check the HR/payroll system, staff records and agreements on company-paid internet or home office."},bank:{title:"Check your address with bank, pension and member organisations",guide:"Check registered details and relevant messages with your bank, pension company, trade union and unemployment fund (a-kasse)."},tax:{title:"Review your preliminary tax assessment (forskudsopgørelse) if circumstances change",guide:"Check whether commuting to work, interest expenses or housing circumstances change your details. Use the Danish Tax Agency's guidance."},insurance:{title:"Arrange insurance cover for both homes and the move",guide:"Ask the insurer to confirm addresses, cover periods, any overlap and cover for belongings in transit and storage. Keep the reply."},houseinsurance:{title:"Sort out house insurance and any change-of-ownership insurance (ejerskifteforsikring)",guide:"Review quotes and agreements with your adviser/insurer. Confirm the date from which cover should apply."},"electric-old":{title:"Report moving out to the electricity supplier at the old address",guide:"Borger.dk states no later than 10 working days before moving out. Confirm the correct end date with the supplier; your liability may continue after the day you move your belongings. Keep the receipt."},"electric-new":{title:"Set up or move the electricity contract to the new home",guide:"Confirm with the electricity supplier that the contract starts on the takeover date. Borger.dk states registration no later than the takeover day. Keep the supplier's confirmation."},"heat-old":{title:"Report moving out to the heating supplier or landlord",guide:"Clarify the end date, meter reading, settlement and who reports the move-out. With central billing the contract may go through the landlord/association."},"heat-new":{title:"Clarify the heating contract and start date in the new home",guide:"Find out who supplies and bills the heating. Arrange registration, access and any servicing."},water:{title:"Clarify the transfer and settlement of water",guide:"Ask the waterworks, landlord or association about reporting, meter readings and settlement at both addresses."},"meter-old":{title:"Photograph and record meters when handing over",guide:"Keep the meter number, reading, date and photos for electricity, water, heating and gas where relevant. Note who the details are sent to."},"meter-new":{title:"Photograph and record meters at takeover",guide:"Keep the opening reading, date and photos. Compare with the takeover documents and agree on reporting."},"final-bills":{title:"Check the final bills for electricity, water and heating",guide:"Compare periods, meter readings and payments on account. Follow up on refunds or unexpected charges."},gas:{title:"Move or cancel your gas supply and related agreements",guide:"Clarify agreements with both the supplier and any grid/service party. Confirm end/start date and meter reading."},"charge-contract":{title:"Cancel, move or transfer your charging subscription",guide:"Find the provider, customer number, lock-in period and notice period. Ask about the options and price for cancelling, moving or transferring. Keep the written acceptance and end date."},"charge-box":{title:"Arrange removal, return or transfer of the EV charger",guide:"Clarify ownership/lease, who may remove it, return label, accessories and any costs. Let qualified professionals handle the installation."},"charge-new":{title:"Plan the charging solution and installation at the new address",guide:"Check the existing installation, ownership of any charger and the need for a new contract. Get quotes and book installation."},"charge-end":{title:"Check the end of the charging contract and the final payment",guide:"Keep the receipt for returned equipment, confirmed termination and final settlement. Check that an old service/reimbursement agreement does not continue unintentionally."},"lease-heat":{title:"Arrange moving, transferring or ending the heat-pump lease",guide:"Find the lessor, contract number, lock-in period and terms. Get a written answer on whether the unit/contract can be moved, taken over by the buyer or ended, and what it costs. Do not assume the contract follows the home automatically."},"lease-heat-book":{title:"Book approved work and coordinate the heat supply",guide:"Agree dates with the lessor and relevant installers. Clarify responsibility for the unit, servicing, warranties and heating in the period between homes."},"lease-heat-confirm":{title:"Keep the signed lease agreement and check the settlement",guide:"Keep the acceptance from the lessor and any new contracting party. Check the old end date, new start date, handover requirements and payments."},internet:{title:"Order a transfer or a new internet connection",guide:"Check coverage at the new address, delivery/installation time, lock-in period and any overlap. Plan a temporary connection if needed."},router:{title:"Return the borrowed router, TV box and other equipment",guide:"Get return instructions and the final deadline from the provider. Photograph serial numbers and keep the drop-off receipt."},subscriptions:{title:"Review TV, streaming, mobile, newspapers and other subscriptions",guide:"Choose keep, move or cancel for each contract. Check address, any household/bundle terms and payments. Moving does not cancel your contracts for you."},memberships:{title:"Move or cancel gym and local memberships",guide:"Go through training, clubs, library registration and local associations. Confirm notice periods and any new memberships."},alarm:{title:"Move or cancel your alarm and monitoring agreement",guide:"Clarify equipment, guard/service agreement, subscription, codes and transfer. Remove old guest access as agreed."},services:{title:"Move or end regular service agreements",guide:"Go through window cleaning, cleaning, gardening help, pest control, ventilation servicing, chimney sweep and other agreements tied to your home."},"tenancy-end":{title:"Review notice, notice period and move-out requirements in your tenancy",guide:"Read the contract and confirm the notice period, redecoration, inspection and keys with the landlord. The suggested plan date is not your contractual notice."},"tenancy-inspection":{title:"Arrange the move-out inspection and document the condition of the home",guide:"Book the inspection, gather the move-in report, take photos and keep agreements on repairs, cleaning and key return."},deposit:{title:"Follow up on the deposit and the move-out statement",guide:"Review the statement, documentation and agreements. Note questions for the landlord and follow up on the refund."},"new-rent":{title:"Review the new tenancy agreement, payments and move-in report",guide:"Keep the contract and receipts. Clarify the move-in inspection and deadlines for reporting defects; create specific tasks with the confirmed dates."},"owner-papers":{title:"Gather the purchase agreement, financing and takeover arrangements",guide:"Go through outstanding items with the bank and adviser. Collect keys, fixtures, the refund statement and relevant deadlines in your documents and budget."},"sale-papers":{title:"Clarify handover requirements and documents when selling",guide:"Go through agreements with the estate agent/adviser on fixtures, cleaning, completion, keys, meters and the transfer date."},association:{title:"Notify the owners', co-op or homeowners' association",guide:"Clarify the contact person, payments, move-in/move-out rules, key fobs, shared facilities and any documents."},"children-school":{title:"Arrange school, after-school care (SFO) and daycare",guide:"Contact the municipality and institutions about places, transfers, withdrawal and start date. Clarify transport and handover of relevant information."},"children-address":{title:"Clarify the children's address and necessary agreements",guide:"With shared residence or parents at different addresses: review the rules and notification with the municipality/borger.dk well in advance. Keep the necessary agreements."},"children-day":{title:"Plan childcare and the children's first evening",guide:"Arrange care on moving day, transport, food and an accessible box of familiar things."},"children-activities":{title:"Move leisure activities and relevant subscriptions for the children",guide:"Go through teams, clubs, school transport and contact details. Note withdrawal and start dates."},"pets-register":{title:"Update your pets' contact details and agreements",guide:"Check relevant registers, microchip details, insurance and vet. Look into new care options if needed."},"pets-day":{title:"Arrange care and safe transport for pets",guide:"Plan transport, food, medicine and a quiet room. Keep animals away from open doors during the move."},car:{title:"Check car insurance, parking and local permits",guide:"Check relevant contact details, parking permit, garage/carport agreement and access to the new address."},benefits:{title:"Notify the relevant authorities of changed housing circumstances",guide:"Go through housing benefit, SU and other benefits you receive. Check with the responsible authority whether you must report changes or apply again."},business:{title:"Update your business address and business agreements",guide:"Check CVR/Virk (the business register), business insurance, invoicing, website and suppliers. Clarify any rules on running a business at the new address."},care:{title:"Coordinate home care, assistive equipment and treatment",guide:"Contact the responsible municipal units and practitioners about handover, delivery and start date so the help is not interrupted."},access:{title:"Plan access, parking and any lift for the removal van",guide:"Clarify the driveway, courtyard, stairs, lift booking and any permit to reserve space."},measure:{title:"Measure doors, stairs and large furniture",guide:"Check that the large items will fit in. Plan disassembly, protection and placement in the new home."},waste:{title:"Plan recycling, donations and disposal",guide:"Book collection as needed, and check the rules for waste/sorting and access to the recycling centre."},"keys-old":{title:"Gather all keys, fobs and remotes for handover",guide:"Find spare copies, letterbox keys, garage openers and lock fobs. Agree on and document the number and recipient."},manuals:{title:"Hand over manuals, service papers and agreed fixtures",guide:"Gather user guides, warranties and service history for what stays in the home. Remove personal accounts from smart devices."},safety:{title:"Find the stopcocks and fuse box, and test the smoke alarms",guide:"Get to know the new home's installations. Find stopcocks and fuses, and check smoke alarms and the necessary contact details."},"waste-new":{title:"Find the waste scheme and collection days at the new address",guide:"See which bins and sorting rules apply, and save collection days or sign up for relevant notifications."},payments:{title:"Check old and new regular payments",guide:"Go through your account for double charges, unfinished subscriptions and missing refunds. Only end payment agreements once the settlement is clear."},"address-followup":{title:"Follow up on post and agreements still using the old address",guide:"Correct the senders and profiles you have missed, and keep the necessary confirmations."},privacy:{title:"Renew or apply for name and address protection",guide:"If you want protection at the new address, it must be applied for together with the change-of-address report. Check the receipt."},proxy:{title:"Clarify powers of attorney for helping with the move",guide:"Obtain the necessary powers of attorney from relevant authorities and companies. Access to the app is not a legal power of attorney. Use your own MitID."},"housing-benefit":{title:"Clarify housing benefit at the old and new address",guide:"Check whether the benefit must be moved, stopped or applied for again. See current conditions and deadlines at Udbetaling Danmark."},student:{title:"Check SU, your study address and Ungdomskort",guide:"Clarify changes with your educational institution and the relevant self-service portals. Also consider your transport to your place of study."},pension:{title:"Clarify your pension if your housing or cohabitation changes",guide:"Contact Udbetaling Danmark or the relevant pension payer if the move changes your circumstances."},"moving-support":{title:"Look into possible help with moving costs and deposit",guide:"If you need support, contact the municipality before entering into agreements or taking on costs. Clarify conditions and the application deadline."},solar:{title:"Transfer or end agreements on solar panels and energy production",guide:"Contact the relevant suppliers and your adviser about change of ownership, settlement, grid registration and any service/financing agreements."},"first-home":{title:"Clarify shared finances, contents and the insurance household",guide:"Agree on payments, ownership of shared items and which insurance policies/subscriptions should continue."},special:{title:"Check special registers, licences and permits",guide:"Go through e.g. firearms permits, hunting/fishing licences or other address-dependent permits. Contact the responsible authority about the requirements."},"packing-supplies":{title:"Get boxes, protection, labels and moving equipment",guide:"Estimate numbers and sizes. Plan a hand truck, blankets, straps, tape and protection for fragile items."},valuables:{title:"Pack valuables, personal papers and electronics separately",guide:"Keep passports, keys, jewellery, essential documents and irreplaceable items under your own supervision. Back up important digital files."},appliances:{title:"Prepare fridge, freezer and white goods for transport",guide:"Plan food consumption, cleaning, any defrosting and disconnection according to the manufacturer's instructions. Arrange professional help where needed."},loft:{title:"Empty the loft, basement, shed, garage and other storage places",guide:"Also go through shared rooms, borrowed items and things kept with family or in storage. Check what comes with the home."},plants:{title:"Plan safe transport of plants, liquids and special items",guide:"Clarify the moving company's rules and pack according to temperature, weight and risk of leakage. Do not transport hazardous materials without relevant guidance."},"helpers-confirm":{title:"Confirm time, roles and contact details with your helpers",guide:"Share the schedule and the necessary addresses. Agree on lifting, breaks, food and who holds keys to each home."},"movers-contract":{title:"Check the price, scope and liability in the moving contract",guide:"Get a written agreement on number of staff, transport, stairs, packing, waiting time and insurance. Clarify surcharges and the procedure in case of damage."},damage:{title:"Go through your belongings and document any transport damage",guide:"Photograph damage and contact the moving company/insurer according to their instructions and deadlines. Keep the agreement and relevant receipts."},"empty-check":{title:"Take final photos and check all rooms at handover",guide:"Check cupboards, window sills, outdoor areas and outbuildings. Keep photos and confirmation of keys and handover."},locks:{title:"Sort out keys, locks and digital access in the new home",guide:"Consider rekeying as agreed with the owner/landlord. Reset relevant smart-home access and make sure you have access to post and shared doors."},"handover-defects":{title:"Follow up on defects, shortcomings and agreements from the takeover",guide:"Gather your observations and send them to the relevant contracting party before the applicable deadlines. Keep the reply and create follow-ups."},neighbours:{title:"Let relevant neighbours know about the move and access",guide:"Agree on consideration for the stairwell, lift, parking and noise, and share a contact number if useful."},commute:{title:"Plan new transport to work, study and activities",guide:"Try out routes and review commuter passes or other transport agreements. Remember changed driving needs in your car insurance, if relevant."},"clean-final":{title:"Finish cleaning and the agreed redecoration",guide:"Check the agreed requirements for oven, extractor hood, drains, cupboards, windows and other rooms. Keep receipts for work ordered."},"packing-return":{title:"Return borrowed boxes, keys and moving equipment",guide:"Clarify return deadlines and keep receipts. Note any deposit that should be refunded."},"ad-preferences":{title:"Check advertising choices and contact preferences at the new address",guide:"Update relevant opt-ins/opt-outs for advertising and deliveries, if you wish."}},trade:{"buy-budget":{title:"Get your finances and purchase budget in place",owner:"You + bank",body:"Review disposable income, one-off costs, financing and any period with two homes. Ask the bank to explain the terms and next steps.",proof:"Written purchase budget and financial plan"},"buy-advisor":{title:"Choose your own adviser",owner:"You",body:"Get quotes with the same scope of work. Clarify who reviews documents, negotiates and completes the deal. The seller's estate agent is not your personal adviser.",proof:"Engagement letter and contact person"},"buy-inspect":{title:"Examine the property and the documents",owner:"You + adviser",body:"Gather the sales particulars, property data, BBR (the building register), easements and relevant reports. Have discrepancies clarified and consider your own technical survey.",proof:"Questions answered in writing"},"buy-association":{title:"Review the association's finances",owner:"Adviser + bank",body:"Ask for the articles, accounts, budget, minutes and maintenance plan. Clarify debt, planned works and future housing costs.",proof:"The adviser's review"},"buy-offer":{title:"Prepare your offer",owner:"You + adviser",body:"Note your maximum price, reasons and desired terms. Assess price, dates and fixtures together. Clarify with your adviser how an offer is made and when it becomes binding.",proof:"Written offer and assumptions"},"buy-terms":{title:"Review the purchase agreement before signing",owner:"You + adviser",body:"Check price, dates, appendices, individual agreements and responsibility for completing the deal. Have unclear terms explained.",proof:"Reviewed version of the agreement"},"buy-conditions":{title:"Clarify the adviser and financing conditions",owner:"Adviser + bank",body:"Have the exact wording, expiry date, time of day and recipient confirmed. The right of withdrawal and the adviser condition are separate tracks. Contact your adviser immediately if in doubt.",proof:"Confirmed deadlines and terms"},"buy-responses":{title:"Follow up on conditions and changes",owner:"Adviser",body:"Follow your adviser's objections, the seller's replies and any extensions of deadlines. Keep written documentation and have it confirmed that all conditions are met.",proof:"Adviser's status on conditions"},"buy-fixtures":{title:"Agree on fixtures and promised works",owner:"You + adviser",body:"Make a precise list of items, condition and any separate price. Describe works, documentation and completion deadline. Have the list incorporated into the agreement.",proof:"Accepted appendix"},"buy-payment":{title:"Have the payment schedule confirmed",owner:"Bank + whoever completes the deal",body:"Follow the agreement on guarantee, deposit and other payments. Confirm payment details through a known contact channel.",proof:"Bank receipts"},"buy-deed":{title:"Follow the deed and land registration",owner:"Completing adviser",body:"Check the deed before signing and get a status on the land registration (tinglysning) and any endorsements. Clarify who follows up.",proof:"Land registration status"},"buy-coop":{title:"Get the co-op transfer in place",owner:"Administrator + adviser",body:"Clarify approval, the transfer agreement, payment and the association's procedure. A co-op flat (andelsbolig) does not follow the same deed process as an owner-occupied home.",proof:"Approved transfer"},"buy-insurance":{title:"Arrange insurance and any early access",owner:"You + insurer",body:"Have the start of cover and liability during early access confirmed. Clarify change-of-ownership insurance (ejerskifteforsikring) if relevant. Note the access day separately from the takeover day.",proof:"Policy and access agreement"},"buy-handover":{title:"Carry out the takeover",owner:"You + seller / estate agent",body:"Go through keys, meters, agreed fixtures and promised works. Take photos and note deviations. Use the app's takeover checklist.",proof:"Takeover notes and photos"},"buy-refund":{title:"Check the refund statement",owner:"You + adviser",body:"Review the allocated items, periods and receipts. Clarify disagreements and payment with whoever prepares the statement.",proof:"Approved statement and payment"},"buy-close":{title:"Have the completion confirmed",owner:"Adviser + bank",body:"Ask for an overall status: are registration, payments and outstanding items in place? Archive the documents. A tick here is only your own record.",proof:"Written completion status"},"sell-proceeds":{title:"Calculate your sale proceeds",owner:"You + bank / estate agent",body:"Get an overview of loan redemption, selling costs and the expected amount after the sale. Also calculate for a lower sale price and a longer selling period.",proof:"Proceeds calculation"},"sell-agent":{title:"Choose an estate agent or help with a private sale",owner:"You",body:"Compare fees, services, outlays, lock-in period and terms if the home is not sold. Agree on who obtains documents and prepares the agreement.",proof:"Agency or adviser agreement"},"sell-docs":{title:"Gather and check the property's details",owner:"You + estate agent",body:"Review BBR (the building register), relevant approvals and documentation. Disclose known material matters and get advice on anything unclear.",proof:"Document folder and corrections"},"sell-reports":{title:"Clarify reports and the home inspection scheme (huseftersynsordningen)",owner:"Estate agent + surveyors",body:"Have the relevant reports and their validity assessed. If the scheme is used, the adviser must ensure correct material and an offer to the buyer at the right time.",proof:"Reports and documented delivery"},"sell-association":{title:"Obtain material from the association",owner:"You + administrator",body:"Gather the association's material and clarify any approval, valuation and sale procedure.",proof:"Association documents"},"sell-market":{title:"Get the home and the sales presentation ready",owner:"You + estate agent",body:"Agree on photos, viewings and pricing. Check the details and the list of what is included.",proof:"Approved sales material"},"sell-negotiate":{title:"Assess offers and terms as a whole",owner:"You + estate agent / adviser",body:"Compare net proceeds, dates, conditions and fixtures. Note your lower limit before negotiating.",proof:"Accepted terms"},"sell-contract":{title:"Review and sign the agreement",owner:"You + adviser",body:"Check all individual promises and conditions. Have the consequences clarified before you sign; do not assume you can freely withdraw afterwards.",proof:"Signed agreement and appendices"},"sell-conditions":{title:"Follow the buyer's conditions and deadlines",owner:"Estate agent + adviser",body:"Follow objections, replies and any changes. Ask your adviser to confirm the status before you consider the deal final.",proof:"Written status"},"sell-works":{title:"Complete promised works and the fixtures list",owner:"You",body:"Do what was agreed and keep documentation. Clarify in writing what stays and what you take with you.",proof:"Appendices, photos and receipts"},"sell-bank":{title:"Follow payment, loan redemption and registration",owner:"Bank + completing adviser",body:"Have guarantees, payment and handling of existing loans confirmed. Clarify when the proceeds can be released; handing over keys is not in itself a release.",proof:"Bank's and adviser's status"},"sell-handover":{title:"Hand over the home as agreed",owner:"You + buyer / estate agent",body:"Arrange the walk-through, keys, meter readings and any early access. Check cleaning, clearing, fixtures and agreed works.",proof:"Handover notes"},"sell-refund":{title:"Reconcile the refund statement and sale proceeds",owner:"You + bank / adviser",body:"Check the refund statement and the final proceeds against your expectations. Ask for an explanation of any differences.",proof:"Statements and receipts"},"sell-close":{title:"Close outstanding items and file the case",owner:"You + adviser",body:"See open questions through and get a completion status. Keep the purchase agreement, appendices, relevant photos and financial statements.",proof:"Complete case file"},"rentIn-budget":{title:"Calculate move-in costs and overlap",owner:"You",body:"Get an overview of rent, payments on account, deposit, prepaid rent and double housing costs. Keep the amounts separate.",proof:"Move-in budget"},"rentIn-verify":{title:"Check the home and the landlord",owner:"You",body:"View the home, check who you are entering into an agreement with, and have the terms of the tenancy clarified.",proof:"Contact and basis of the agreement"},"rentIn-contract":{title:"Review the tenancy agreement",owner:"You + tenant adviser",body:"Review rent, maintenance, special terms, fixed term and notice. Clarify whether the home is private or social housing (almen); rules and documents may differ.",proof:"Reviewed contract"},"rentIn-payment":{title:"Agree on and document payment",owner:"You + landlord",body:"Confirm amounts, payee and deadlines. Keep the contract and receipts.",proof:"Payment receipt"},"rentIn-inspection":{title:"Go through the home at move-in",owner:"You + landlord",body:"Take dated photos, read the meters and note keys and defects. Ask for the relevant move-in report. Clarify which inspection rules apply.",proof:"Report and photos"},"rentIn-defects":{title:"Report move-in defects in writing",owner:"You",body:"Examine the home thoroughly and send the list of defects on time. Have the deadline confirmed under the applicable rules; do not wait until the moving work is finished.",proof:"Sent defects list and receipt"},"rentIn-follow":{title:"Follow up on defects and payments",owner:"You + landlord",body:"Follow the agreed repairs and check the first rent charge. Keep the documentation for when you later move out.",proof:"Resolved outstanding items"},"rentOut-notice":{title:"Check notice and handover requirements",owner:"You + adviser if any",body:"Read the contract and the relevant rules. Clarify notice period, handover and the last payment day. They are not necessarily the same date.",proof:"Confirmed dates"},"rentOut-terminate":{title:"Give notice on the tenancy and keep the confirmation",owner:"You + landlord",body:"Send the notice as agreed and have receipt and dates confirmed. Provide your new contact address in good time.",proof:"Notice and reply"},"rentOut-prepare":{title:"Prepare the handover and inspection",owner:"You",body:"Find the move-in report and photos. Clarify maintenance, clearing and cleaning before you order any work.",proof:"Agreement on inspection and documentation"},"rentOut-inspection":{title:"Attend the move-out inspection and key handover",owner:"You + landlord",body:"Take photos, read the meters and get a receipt for the keys. Read the report and note any disagreements.",proof:"Move-out report and receipt"},"rentOut-deposit":{title:"Check the move-out statement and deposit",owner:"You + landlord / adviser",body:"Compare claims and receipts with the contract and reports. Ask for an explanation of unclear items and seek advice in case of dispute.",proof:"Settlement and documentation"}},advice:{forbehold:{phase:"Before signing",title:"What does an adviser condition protect me against?",term:"Adviser condition (rådgiverforbehold)",definition:"An agreed condition that the deal is subject to your adviser's approval.",answer:"The wording of the condition determines what the adviser can do and when objections must be received. It is not automatically included in every agreement. The statutory withdrawal period runs in parallel, not afterwards.",who:"Buyer's adviser",when:"Before signing; then follow the exact deadline in the agreement.",action:"Have the adviser condition and objection deadline confirmed",ask:"Does the condition cover the whole deal, who must receive the reply, and by what date and time?"},fortrydelse:{phase:"During the deal",title:"Can the buyer or seller withdraw?",term:"Right of withdrawal (fortrydelsesret)",definition:"The buyer's statutory option to withdraw in covered consumer transactions.",answer:"For a home the buyer will live in, the general rule is six working days and compensation of 1% of the purchase price. Both the written notice and the payment must be on time; further conditions may apply. The seller has no equivalent statutory right. An adviser condition is a separate track.",who:"Buyer and buyer's adviser",when:"Contact your adviser immediately if you want out of the deal.",action:"Clarify the option of withdrawing from the deal",ask:"Which basis can I use, what does it cost, and when exactly does my deadline expire?"},aftale:{phase:"Before signing",title:"What should the purchase agreement contain?",term:"Purchase agreement (købsaftale)",definition:"The contract on price, takeover and the other terms of the deal.",answer:"The sales particulars and individual agreements can form part of the contract. Promises such as completing work or items included must be described clearly. Read the final version and the appendices, even if you have seen an earlier draft.",who:"Buyer, seller and their advisers",when:"Before signing and with every addendum.",action:"Review the special terms and appendices of the purchase agreement",ask:"Are all agreements on fixtures, repairs, dates and conditions written in?"},bank:{phase:"Before signing",title:"Is the bank's loan pre-approval enough to buy?",term:"Financing condition (finansieringsforbehold)",definition:"An agreed condition that the financing can be approved.",answer:"Have the bank take a position on the specific home and deal. Clarify the need for a condition with your adviser before you sign. A budget or a preliminary purchase budget should not stand alone as your confirmation that all conditions are met.",who:"Buyer, bank and buyer's adviser",when:"Before signing and before any agreed bank deadline.",action:"Get written bank approval for the specific home",ask:"Which conditions are missing, and should a financing condition be added or extended?"},garanti:{phase:"During the deal",title:"What is the difference between a bank guarantee and a deposit?",term:"Bank guarantee (bankgaranti)",definition:"The bank's security for payment of the agreed purchase price.",answer:"With a deposit, the money is paid in according to the terms of the deal. A bank guarantee and a cash deposit are separate steps; deadlines and amounts follow the purchase agreement. Have the bank coordinate the payments with whoever completes the deal.",who:"Buyer's bank and buyer",when:"After signing and up to the takeover, as agreed.",action:"Confirm amounts and dates for guarantee and deposit",ask:"When do I transfer what, and who confirms that the security is in place?"},skoede:{phase:"During the deal",title:"Who prepares the deed, and what is land registration?",term:"Deed and land registration (skøde og tinglysning)",definition:"The deed records the change of ownership; land registration secures the right publicly.",answer:"Completion (berigtigelse) is the practical execution: deed, registration, settlement and cancellation of relevant loans. The purchase agreement must clarify who handles it. Buyer and seller sign themselves or via power of attorney.",who:"The completing adviser, the parties and the banks",when:"After the agreement is made; follow the agreed processing deadlines.",action:"Confirm responsibility and timeline for deed and completion",ask:"Who prepares the deed, who checks it, and when do we sign?"},maegler:{phase:"Before signing",title:"Is the seller's estate agent also my adviser?",term:"Buyer's adviser (køberrådgiver)",definition:"An adviser who looks after the buyer's interests in the deal.",answer:"The seller's estate agent represents the seller. Helping with documents or practical questions does not make the agent the buyer's independent adviser. Agree precisely what your own adviser reviews and follows up on.",who:"The buyer chooses their own adviser",when:"Before you commit to the deal.",action:"Agree the scope of your buyer's advice",ask:"Are conditions, document review, deed and refund statement included in the price?"},rapport:{phase:"Before signing",title:"Is a condition report a guarantee for the house?",term:"Condition report (tilstandsrapport)",definition:"A professional review of visible damage under the home inspection scheme.",answer:"The reports describe visible conditions and the state of the electrical installations. They are not a complete guarantee against all problems. Have unclear findings assessed by your own expert, including possible follow-on work. The scheme is normally not used for ordinary owner-occupied flats.",who:"The seller obtains it; buyer and expert review it",when:"Before making an offer and before relevant conditions expire.",action:"Have the main report findings and repairs assessed",ask:"What should be examined more closely, and what costs could the findings lead to?"},ejerskifte:{phase:"Before completion",title:"Who pays for the change-of-ownership insurance?",term:"Change-of-ownership insurance (ejerskifteforsikring)",definition:"Insurance against certain hidden building defects under the terms of the policy.",answer:"Under the home inspection scheme, the seller offers to pay at least half the premium of the quote presented. The buyer can choose another insurer, but the seller's contribution follows the reference quote. Compare cover, exclusions and excess; not all defects are covered.",who:"The buyer chooses; the seller contributes under the scheme",when:"Obtain and accept a quote in good time before takeover, according to the insurance terms.",action:"Compare change-of-ownership insurance and confirm the seller's contribution",ask:"What is excluded, and what is the final deadline for taking out this particular policy?"},ansvar:{phase:"Before signing",title:"As a seller, am I free of all liability with a home inspection?",term:"Home inspection scheme (huseftersynsordningen)",definition:"A scheme that, under certain conditions, limits the seller's liability for defects.",answer:"It requires timely reports, an insurance quote and a payment declaration. The scheme is not a general exemption from all liability. Have your adviser assess special disclosures, warranties and matters the scheme does not cover.",who:"Seller and seller's adviser",when:"Before the buyer makes an offer.",action:"Check that the home inspection documents were handed over on time",ask:"Are all conditions met, and which matters can I still be liable for?"},oplysninger:{phase:"Before signing",title:"What must I disclose about damage and renovation?",term:"Seller's disclosure form (sælgeroplysningsskema)",definition:"The seller's information about the property's condition for the home inspection.",answer:"Answer the questions according to your actual knowledge. Gather documentation on previous damage and work. Distinguish between what you know and what you cannot document; get help when in doubt rather than guessing.",who:"Seller, expert and adviser",when:"When the report is prepared and before the agreement is made.",action:"Gather documentation and clarify uncertain seller disclosures",ask:"Which known matters and previous works must be described or examined more closely?"},bbr:{phase:"Before signing",title:"Does BBR registration mean an extension is legal?",term:"BBR",definition:"The Building and Housing Register (BBR) describes the building's actual conditions.",answer:"No. BBR can also contain matters that have not been approved. Compare the registration with the home and the municipality's building file. Clarify deviations, permits and responsibility with your adviser and the municipality before basing the deal on a particular floor area or use.",who:"Owner, municipality and the parties' advisers",when:"Before signing or before relevant conditions expire.",action:"Compare BBR, building permits and the home's actual layout",ask:"Are the floor area and use approved, and who must handle any deviations?"},dokumenter:{phase:"Before signing",title:"Which documents should my adviser read?",term:"Easement (servitut)",definition:"A right or restriction attached to the property.",answer:"The property's documents can reveal costs, restrictions and planning matters. Ask your adviser to review property data, easements and the local plan, among other things, against your plans for the home. Ask specifically about extensions, use and access.",who:"Buyer and buyer's adviser",when:"Before the deal becomes unconditional.",action:"Have documents and restrictions reviewed",ask:"Are there provisions that prevent the use or conversion I want?"},noegler:{phase:"Before completion",title:"Can we get or hand over keys before the takeover?",term:"Access day (dispositionsdag)",definition:"The day the buyer gets use of the property before the legal takeover day.",answer:"Early access affects risk, insurance, maintenance and consumption, among other things. The legal takeover day and the financing do not change automatically. Get the terms in writing, and have bank, adviser and insurer confirm that everything is ready.",who:"Buyer, seller, advisers and insurer",when:"Before anyone gets access or starts renovating.",action:"Agree access day, consumption and start of insurance in writing",ask:"When does the risk pass, and what must be fulfilled before keys are handed over?"},overdragelse:{phase:"Before completion",title:"What do we do on the takeover day?",term:"Key handover (nøgleoverdragelse)",definition:"The practical handover of the home and its keys.",answer:"Go through the home, read the meters and hand over all keys and relevant manuals. Note unresolved matters and take photos. Agree who sends the readings and notifies the utility companies, so the task does not fall between the parties.",who:"Buyer and seller; often with the estate agent",when:"On the agreed key/access day.",action:"Arrange the walk-through, meter readings and handover of keys",ask:"Are promised works finished, and who follows up in writing on outstanding items?"},refusion:{phase:"After completion",title:"What is the refund statement, and who prepares it?",term:"Refund statement (refusionsopgørelse)",definition:"Settlement of financial items between buyer and seller.",answer:"The statement allocates relevant prepaid costs and amounts owed between the parties. Some consumption items are settled directly with the supplier and must not be settled twice. The purchase agreement determines who prepares the statement and when.",who:"Whoever is responsible under the purchase agreement; the parties provide receipts",when:"After takeover, before the deadline in the agreement.",action:"Confirm responsibility, receipts and deadline for the refund statement",ask:"Which items are missing, has anything already been settled, and who owes whom?"},provenu:{phase:"After completion",title:"When do I get the money from the sale?",term:"Release of funds (frigivelse)",definition:"When the deposited purchase price can be paid out under the conditions of the deal.",answer:"The money is not necessarily available just because the keys have been handed over. The deed, mortgages and agreed conditions must be dealt with. In some situations, release against a bank guarantee can be agreed. Get a specific status before you spend the proceeds.",who:"Seller's bank and the completing adviser",when:"Around the takeover; once the conditions are fulfilled.",action:"Have the expected release date and sale proceeds confirmed",ask:"What is still outstanding, and when is the money actually available?"},mangler:{phase:"After completion",title:"Who do I contact if I discover damage?",term:"Defect (mangel)",definition:"A matter which, on a specific assessment, may deviate from what was agreed or could be expected.",answer:"Damage does not automatically give you a claim against the seller. Cover and liability depend on the agreement, reports, insurance and knowledge, among other things. Document the matter and contact your adviser and the relevant insurer quickly; clarify the procedure before major repairs, except for necessary damage limitation.",who:"Buyer, adviser and the relevant insurer",when:"As soon as the problem is discovered.",action:"Document the damage and clarify the complaint with your adviser",ask:"Who must receive the complaint, which deadlines apply, and how do I secure the documentation?"},depositum:{phase:"Before signing",title:"Is a deposit the same as prepaid rent?",term:"Deposit (depositum)",definition:"Security for the landlord's possible claims when the tenancy ends.",answer:"In private residential tenancies, the landlord can generally require up to three months' rent as a deposit and up to three months' prepaid rent. Prepaid rent is used at the end of the tenancy; the deposit is not the same thing. Social housing (almene boliger) has other arrangements.",who:"Tenant and landlord",when:"Before the contract and payment; again when giving notice.",action:"Check the deposit, prepaid rent and first payment",ask:"Which amounts cover what, and when can the prepaid rent be used?"},lejemangler:{phase:"Before completion",title:"How do I record defects in my new rental home?",term:"Move-in report (indflytningsrapport)",definition:"Documentation of the condition of the tenancy at move-in.",answer:"Go through the home and send defects to the landlord in writing. In private residential tenancies the starting point is a deadline of two weeks from the start of the tenancy; there are exceptions for e.g. hidden defects. Attend the inspection if you are called to one, and keep the report, photos and a receipt for your notification.",who:"Tenant and landlord",when:"At takeover and immediately afterwards.",action:"Photograph and submit move-in defects to the landlord",ask:"What is the exact deadline in my tenancy, and has the landlord received the list?"},opsigelse:{phase:"Before completion",title:"When should I give notice on my rental home?",term:"Notice period (opsigelsesvarsel)",definition:"The period between giving notice and the end of the tenancy.",answer:"Read the contract's terms on notice, fixed term and handover. Moving out earlier does not automatically stop the rent. Clarify the end date, any re-letting and key return in writing with the landlord; get tenant advice in case of disagreement.",who:"Tenant and landlord",when:"Before you tie your moving date and costs together.",action:"Have the notice, last rent day and handover confirmed",ask:"Until which date am I liable, and can the home be re-let earlier?"},flytning:{phase:"After completion",title:"Is my moving date the same as the takeover date?",term:"Change of address in the National Register (folkeregisterflytning)",definition:"Registration of your actual place of residence.",answer:"The date of keys or change of ownership is not necessarily the day you actually move. Report your move to the municipality no later than five days after moving. Keep the homes' contract dates separate from your actual moving date.",who:"You and the municipality",when:"When you move; no later than five days after.",action:"Report your actual move on borger.dk",ask:"On which date do I actually take up residence at the address?"},andel:{phase:"Before signing",title:"What should I examine with a co-op flat?",term:"Key information (nøgleoplysninger)",definition:"Information about the co-op flat (andelsbolig) and the association's finances.",answer:"Look at the price, articles, accounts, budget and key information together. The seller must hand over the relevant documents before the agreement, often with help from the association. Have your bank and adviser assess the association's debt and costs together with your own finances.",who:"Seller, association, buyer's bank and adviser",when:"Before agreeing to the transfer.",action:"Review the co-op flat's documents and the association's finances",ask:"What could change the monthly housing charge, and have the necessary documents been handed over?"},ejerforening:{phase:"Before signing",title:"How does the owners' association affect my finances?",term:"Allocation ratio (fordelingstal)",definition:"The key for allocating shared costs between owner-occupied flats.",answer:"Accounts, budget, articles and minutes reveal more than the current shared costs. Look into planned works, financing and decisions that could lead to extra payments. Also clarify the division of maintenance responsibility between you and the association.",who:"Buyer, adviser and the association's administrator",when:"Before the deal becomes unconditional.",action:"Read the owners' association's finances and decisions",ask:"Have major works been decided or are they expected, and what will my share be?"}},phases:["Before signing","During the deal","Before completion","After completion"],tips:[["Temporary rental between selling and buying","Keep all tracks active at the same time. Record each address and key/handover date separately. Compare the dates, and budget for double rent, an extra move and any storage. Do not give notice on your rental based solely on an expected purchase date."],["Renting: in and out","Keep the contract, reports, photos, payments and written agreements. Distinguish between private and social housing (almen) tenancies. Have doubts about maintenance, defect deadlines, notice or deposit assessed by a tenant adviser."],["Negotiation","Prepare your limit before the conversation. Write down three priorities: price, timing and what is included. Compare the whole package and your total costs, not just the discount. Have your adviser check an offer and its conditions."],["Fixtures and accessories","Write down exactly which items are included, e.g. curtains, lamps or garden machinery. Describe model, condition and any separate price. Distinguish between owned items and lease agreements. Have the agreement incorporated into the deal's documents."],["Takeover and early access","Keep the access day, takeover day and moving day separate. With early access, liability, consumption, insurance and permitted works must be agreed in writing."],["Promised repairs","Describe what is to be done, by whom and when. Agree how the work is documented and checked. Get your adviser's help if it is not finished as agreed."],["Conditions and withdrawal","The adviser condition, financing condition and statutory right of withdrawal are different things. Rely on the specific agreement and your adviser's confirmed deadlines; the app does not calculate them."],["When are we completely done?","Signing, fulfilled conditions, takeover and financial completion are separate milestones. Get professional confirmation at each relevant step. Ticking a box in the app does not change the legal status of the deal."]],advisers:{intro:[["Lawyer / legal buyer's adviser","agreement, documents and conditions."],["Bank","finances and financing."],["Building surveyor","the technical condition of the home."],["Estate agent","sale, marketing and contact with buyers."],["Tenant adviser","contract, move-in, notice and settlement."]],links:[{href:"https://www.advokatnoeglen.dk/",title:"Find a lawyer",description:"Search by area and speciality in Advokatnøglen"},{href:"https://boligejer.dk/find-konsulent",title:"Find a surveyor",description:"Go straight to the consultant search on Boligejer.dk"}]}};export{e as default};
